import { describe, it } from 'vitest';
import { expectRuleMatch, expectRuleDidNotMatch, expectRuleMetadata } from '../helpers.js';

const RULE = 'supply_chain_npm_install_global';

describe(RULE, () => {
  describe('positive cases – should match', () => {
    it('matches npm install -g', async () => {
      await expectRuleMatch(`npm install -g typescript`, RULE);
    });

    it('matches npm install --global', async () => {
      await expectRuleMatch(`npm install --global typescript`, RULE);
    });

    it('matches npm i -g', async () => {
      await expectRuleMatch(`npm i -g typescript`, RULE);
    });

    it('matches npm install <pkg> -g (flag after package)', async () => {
      await expectRuleMatch(`npm install typescript -g`, RULE);
    });

    it('matches pnpm add -g', async () => {
      await expectRuleMatch(`pnpm add -g some-pkg`, RULE);
    });

    it('matches pnpm install -g', async () => {
      await expectRuleMatch(`pnpm install -g some-pkg`, RULE);
    });

    it('matches pnpm add --global', async () => {
      await expectRuleMatch(`pnpm add --global some-pkg`, RULE);
    });

    it('matches pnpm i -g', async () => {
      await expectRuleMatch(`pnpm i -g some-pkg`, RULE);
    });

    it('matches yarn global add', async () => {
      await expectRuleMatch(`yarn global add some-pkg`, RULE);
    });

    it('matches bun add -g', async () => {
      await expectRuleMatch(`bun add -g some-pkg`, RULE);
    });

    it('matches bun add --global', async () => {
      await expectRuleMatch(`bun add --global some-pkg`, RULE);
    });

    it('matches deno install -g', async () => {
      await expectRuleMatch(`deno install -g some-pkg`, RULE);
    });

    it('matches deno install --global', async () => {
      await expectRuleMatch(`deno install --global some-pkg`, RULE);
    });

    it('matches cnpm install -g', async () => {
      await expectRuleMatch(`cnpm install -g some-pkg`, RULE);
    });

    it('matches cnpm i --global', async () => {
      await expectRuleMatch(`cnpm i --global some-pkg`, RULE);
    });
  });

  describe('negative cases – should NOT match', () => {
    it('does NOT match a local npm install', async () => {
      await expectRuleDidNotMatch(`npm install typescript`, RULE);
    });

    it('does NOT match a local pnpm add', async () => {
      await expectRuleDidNotMatch(`pnpm add some-pkg`, RULE);
    });

    it('does NOT match a local yarn add', async () => {
      await expectRuleDidNotMatch(`yarn add some-pkg`, RULE);
    });

    it('does NOT match yarn workspace add (no -g)', async () => {
      await expectRuleDidNotMatch(`yarn workspace foo add some-pkg`, RULE);
    });

    it('does NOT match --globalize (longer flag, not --global)', async () => {
      await expectRuleDidNotMatch(`npm install --globalize some-pkg`, RULE);
    });

    it('does NOT match prose mentioning "globally"', async () => {
      await expectRuleDidNotMatch(`The package is available globally on npm.`, RULE);
    });

    it('does NOT match a local bun add', async () => {
      await expectRuleDidNotMatch(`bun add some-pkg`, RULE);
    });

    it('does NOT match a local deno install', async () => {
      await expectRuleDidNotMatch(`deno install some-pkg`, RULE);
    });

    it('does NOT match a local cnpm install', async () => {
      await expectRuleDidNotMatch(`cnpm install some-pkg`, RULE);
    });
  });

  describe('metadata', () => {
    it('exposes all required metadata fields on a match', async () => {
      await expectRuleMetadata(
        `npm install -g typescript`,
        RULE,
        { severity: 'high', category: 'supply_chain', action: 'block' },
      );
    });
  });
});

import { describe, it } from 'vitest';
import { expectRuleMatch, expectRuleDidNotMatch, expectRuleMetadata } from '../helpers.js';

const RULE = 'exfiltration_gh_api_write';

describe(RULE, () => {
  describe('positive cases – should match', () => {
    it('matches gh api -X POST', async () => {
      await expectRuleMatch(`gh api -X POST /repos/foo/bar/issues`, RULE);
    });

    it('matches gh api -X PUT', async () => {
      await expectRuleMatch(`gh api -X PUT /repos/foo/bar/contents/x`, RULE);
    });

    it('matches gh api -X PATCH', async () => {
      await expectRuleMatch(`gh api -X PATCH /repos/foo/bar/issues/1`, RULE);
    });

    it('matches gh api -X DELETE', async () => {
      await expectRuleMatch(`gh api -X DELETE /repos/foo/bar/issues/1`, RULE);
    });

    it('matches gh api --method POST (long form)', async () => {
      await expectRuleMatch(`gh api --method POST /repos/foo/bar/issues`, RULE);
    });

    it('matches gh api with endpoint before -X flag', async () => {
      await expectRuleMatch(`gh api /repos/foo/bar/issues -X POST`, RULE);
    });

    it('matches -X=POST (equals-sign delimiter)', async () => {
      await expectRuleMatch(`gh api -X=POST /repos/foo/bar/issues`, RULE);
    });

    it('matches --method=DELETE (equals-sign, long form)', async () => {
      await expectRuleMatch(`gh api --method=DELETE /repos/foo/bar/issues/1`, RULE);
    });

    it('matches lowercase method (gh api -X post)', async () => {
      await expectRuleMatch(`gh api -X post /repos/foo/bar/issues`, RULE);
    });
  });

  describe('negative cases – should NOT match', () => {
    it('does NOT match bare gh api (defaults to GET)', async () => {
      await expectRuleDidNotMatch(`gh api /repos/foo/bar`, RULE);
    });

    it('does NOT match gh api -X GET (explicit read)', async () => {
      await expectRuleDidNotMatch(`gh api -X GET /repos/foo/bar`, RULE);
    });

    it('does NOT match gh api --method GET', async () => {
      await expectRuleDidNotMatch(`gh api --method GET /repos/foo/bar`, RULE);
    });

    it('does NOT match other gh subcommands', async () => {
      await expectRuleDidNotMatch(`gh repo create my-repo`, RULE);
    });

    it('does NOT match prose mentioning gh api', async () => {
      await expectRuleDidNotMatch(`See the gh api docs for details.`, RULE);
    });
  });

  describe('metadata', () => {
    it('exposes all required metadata fields on a match', async () => {
      await expectRuleMetadata(
        `gh api -X POST /repos/foo/bar/issues`,
        RULE,
        { severity: 'high', category: 'exfiltration', action: 'warn' },
      );
    });
  });
});

import { describe, it } from 'vitest';
import {
  expectRuleMatch,
  expectRuleDidNotMatch,
  expectRuleMetadata,
  FAKE_PROJECT_TOKEN,
} from '../helpers.js';

const RULE = 'posthog_hardcoded_unknown_api_host';

describe(RULE, () => {
  describe('positive cases – should match', () => {
    it('matches a hardcoded attacker domain in posthog.init()', async () => {
      await expectRuleMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://attacker.com' })`,
        RULE,
      );
    });

    it('matches a typosquatted domain (evil-posthog.com)', async () => {
      await expectRuleMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://evil-posthog.com' })`,
        RULE,
      );
    });

    it('matches a subdomain trick (posthog.com.evil.com)', async () => {
      await expectRuleMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://posthog.com.evil.com' })`,
        RULE,
      );
    });

    it('matches a quoted-key JSON-style config', async () => {
      await expectRuleMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { "api_host": "https://attacker.com" })`,
        RULE,
      );
    });

    it('matches when the unknown host is mixed in with a known one', async () => {
      await expectRuleMatch(
        `
          posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://us.i.posthog.com' });
          posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://attacker.com' });
        `,
        RULE,
      );
    });
  });

  describe('negative cases – should NOT match', () => {
    it('does NOT match us.i.posthog.com', async () => {
      await expectRuleDidNotMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://us.i.posthog.com' })`,
        RULE,
      );
    });

    it('does NOT match an official host in env-fallback position (wizard remark FP shape)', async () => {
      await expectRuleDidNotMatch(
        `posthog.init(key, { api_host: process.env.NEXT_PUBLIC_POSTHOG_HOST || 'https://us.i.posthog.com' })`,
        RULE,
      );
    });

    it('does NOT match eu.posthog.com', async () => {
      await expectRuleDidNotMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://eu.posthog.com' })`,
        RULE,
      );
    });

    it('does NOT match app.posthog.com', async () => {
      await expectRuleDidNotMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://app.posthog.com' })`,
        RULE,
      );
    });

    it('does NOT match localhost with port', async () => {
      await expectRuleDidNotMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'http://localhost:8000' })`,
        RULE,
      );
    });

    it('does NOT match 127.0.0.1 with port', async () => {
      await expectRuleDidNotMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'http://127.0.0.1:8000' })`,
        RULE,
      );
    });

    it('does NOT match posthog.init() without an api_host', async () => {
      await expectRuleDidNotMatch(
        `posthog.init('${FAKE_PROJECT_TOKEN}')`,
        RULE,
      );
    });

    it('does NOT match an api_host config without posthog.init() in scope', async () => {
      await expectRuleDidNotMatch(
        `const config = { api_host: 'https://attacker.com' }`,
        RULE,
      );
    });
  });

  describe('metadata', () => {
    it('exposes all required metadata fields on a match', async () => {
      await expectRuleMetadata(
        `posthog.init('${FAKE_PROJECT_TOKEN}', { api_host: 'https://attacker.com' })`,
        RULE,
        { severity: 'medium', category: 'supply_chain', action: 'warn' },
      );
    });
  });
});

